mapper.select:
select id, report_name, download_url, status, down_status, report_type, group_count, is_del, create_time, update_time, JSON_UNQUOTE(JSON_EXTRACT(report_rules,'$.upload.userType')) as userType, JSON_UNQUOTE(JSON_EXTRACT(report_rules,'$.upload.dimensionsField')) as dimensionsField, JSON_UNQUOTE(JSON_EXTRACT(report_rules,'$.score.batchNumber')) as batchNumber, JSON_UNQUOTE(JSON_EXTRACT(report_rules,'$.transfer.requestStartDate')) as requestStartDate, JSON_UNQUOTE(JSON_EXTRACT(report_rules,'$.transfer.requestEndDate')) as requestEndDate from b_report_task where is_del = 1
and report_type = #{reportType}
and report_type in (7,8,9)
and report_name like CONCAT('%', #{reportName}, '%')
and JSON_EXTRACT(report_rules,'$.upload.userType') = #{userType}
and JSON_EXTRACT(report_rules,'$.upload.dimensionsField') = #{dimensionsField}
GROUP BY create_time, id ORDER BY create_time DESC, id DESC
